      "originality": {
        "or1": {
          "v": 1,
          "quote": "Justice and Mercy together require a cost-bearing source beyond the damaged order itself. That source must preserve truth while making restoration possible. That source is Grace.",
          "why": "A variant of the Anselmian satisfaction/atonement logic, re-cast as a 24-step chain from ontology to the Cross."
        },
        "or2": {
          "v": 0,
          "quote": ""
        },
        "or3": {
          "v": 0,
          "quote": ""
        },
        "or4": {
          "v": 1,
          "quote": "The whole causal chain in 24 steps",
          "why": "Adds a numbered stepwise structure, but the steps are prose links rather than formalized inference rules."
        }
      },
      "weakest_link": "The step from 'adversarial action creates real debt' to 'perfect Justice requires that this be truthfully answered and paid' -- a contested retributive-justice premise carrying the whole chain.",
      "develop_next": "Justify the retributive-justice premise (and the necessity of a cost-bearing source) rather than asserting it as a step.",
      "case_map": ["K04", "K14", "K18"],
      "domain": "theology"
    },
    {
      "id": "G16",
      "name": "Progressive revelation as pedagogy",
      "speaker": "Framework author",
      "conclusion": "God reveals progressively because receivers cannot parse the full signal at once; He builds the reference frame piece by piece.",
