        "or2": {
          "v": 1,
          "quote": "He meets them in slavery -- and turns their deliverance into the vocabulary through which rescue can be understood.",
          "why": "Uses the specific exodus-wilderness-law-exile sequence as ordered vocabulary-building, a more granular reading than the classical version."
        },
        "or3": {
          "v": 1,
          "quote": "because the child does not have the reference frame to receive it",
          "why": "Imports cognitive/developmental 'reference frame' framing into theology, though only as an analogy."
        },
        "or4": {
          "v": 0,
          "quote": ""
